from pathlib import Path
import math,random,json,hashlib
p=Path(__file__).parent;top=(1<<63)-1
large=[1<<31,3**19,5**13,65521**2,(1<<32)-1,4_000_000_000,3**20]
rows={}
def add(m,n,k,v,kind):
 assert 0<=n<=top and 0<=k<=n
 old=rows.get((m,n,k))
 if old is not None:assert old[0]==v
 rows[m,n,k]=(v,kind)
for m in large:
 ns={top,top-1,top-31,top-128,m-1,m,m+1,2*m-1,2*m,2*m+1,31,32,33,127,128,129,4095,4096,4097,8191,8192,8193}
 for n in sorted(ns):
  for k in [2,3,4,5,7,16,31,32,63,64,127,128]:
   if k<=n:add(m,n,k,math.comb(n,k)%m,'math_comb_small_k')
 for k in [100003,1000003]:
  n=2*m
  if math.gcd(k,m)==1 and k<=n:add(m,n,k,0,'n_multiple_mod_k_coprime')
for n in [31,32,33,127,128,129,255,256,257,4095,4096,4097,8191,8192,8193,20000,50000,200000]:
 for k in sorted({n//2,n//3,n//7}):
  exact=math.comb(n,k)
  for m in large:add(m,n,k,exact%m,'math_comb_large_k')
for prime,e in [(2,31),(3,19),(5,13),(65521,2),(3,20)]:
 m=prime**e;power=1;exponent=0
 while power<=top//prime:power*=prime;exponent+=1
 for k in [100003,100004]:
  t=0;temp=k
  while temp>=prime:temp//=prime;t+=1
  assert exponent-t>=e
  add(m,power-1,k,(m-1 if k&1 else 1),'p_power_minus_one_congruence')
def factor(m):
 result=[];p0=2
 while p0*p0<=m:
  if m%p0==0:
   q=1;e=0
   while m%p0==0:m//=p0;q*=p0;e+=1
   result.append((p0,q,e))
  p0+=1
 if m>1:result.append((m,m,1))
 return result
def residue_binomial(n,k,prime,q,e):
 r=n-k;a=k;b=r;carry=0;v=0
 while a or b:
  carry=(a%prime+b%prime+carry)>=prime;v+=carry;a//=prime;b//=prime
 if v>=e:return 0
 phi=q-q//prime;unit=1
 for residue in range(1,q):
  if residue%prime==0:continue
  x=n;y=k;z=r;count=0
  while x:
   count+=(x+q-residue)//q-(y+q-residue)//q-(z+q-residue)//q
   x//=prime;y//=prime;z//=prime
  unit=unit*pow(residue,count%phi,q)%q
 return unit*pow(prime,v,q)%q
def independent(n,k,m):
 value=0;step=1
 for prime,q,e in factor(m):
  r=residue_binomial(n,k,prime,q,e)
  t=(r-value)*pow(step,-1,q)%q
  value+=step*t;step*=q
 return value
rng=random.Random(411681)
small=[8,16,27,81,243,256,625,729,1024,2401,3125,4096,360,720720,510510]
for m in small:
 for i in range(12):
  n=rng.randrange(1<<55,top);k=rng.randrange(2,n-1)
  add(m,n,k,independent(n,k,m),'unit_residue_multiplicities')
 fs=factor(m)
 if len(fs)==1:
  prime,q,e=fs[0];power=1
  while power<=top//prime:power*=prime
  for i in range(12):
   n=power-1;k=rng.randrange(2,n-1)
   add(m,n,k,independent(n,k,m),'unit_residue_multiplicities_nonzero')
# Cross-check the residue multiplicity oracle with exact arithmetic on manageable n.
refchecks=0
for m in small:
 for i in range(20):
  n=rng.randrange(1,300);k=rng.randrange(n+1)
  assert independent(n,k,m)==math.comb(n,k)%m;refchecks+=1
text=''.join(f'{m} {n} {k} {v} {kind}\n' for (m,n,k),(v,kind) in sorted(rows.items()))
(p/'extended_fixtures.txt').write_text(text)
meta={'rows':len(rows),'large_moduli':large,'small_moduli':small,'independent_oracle_exact_crosschecks':refchecks,'sha256':hashlib.sha256(text.encode()).hexdigest(),'proofs':{'n_multiple_mod_k_coprime':'k*C(n,k)=n*C(n-1,k-1), so invertible k and n=0 modm imply C=0 modm.','p_power_minus_one_congruence':'C(p^J-1,k)=(-1)^k product_i(1-p^J/i) in p-adic units; J-floor(log_p k)>=e makes each factor1 modp^e.','unit_residue_multiplicities':'Count each invertible residue in the p-free parts of n!,k!,r! at every p division level; reduce signed occurrence difference modulo phi(p^e), then independently count addition carries and combine CRT incrementally.'}}
(p/'fixture_metadata.json').write_text(json.dumps(meta,indent=2));print(meta)

