#include <algorithm>
#include <array>
#include <bit>
#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <initializer_list>
#include <iostream>
#include <limits>
#include <random>
#include <stdexcept>
#include <vector>
#define private public
#include BINOMIAL_SOURCE
#undef private
static std::uint64_t checks=0;
#define REQUIRE(x)do{++checks;if(!(x))std::abort();}while(false)
static std::uint32_t inverse_bits(std::uint32_t a){std::uint32_t r=1;for(unsigned bit=1;bit<32;++bit)if((static_cast<std::uint64_t>(a)*r)&(std::uint64_t{1}<<bit))r|=std::uint32_t{1}<<bit;return r;}
int main(){using U=std::uint64_t;constexpr U top=std::numeric_limits<std::int64_t>::max();std::mt19937_64 rng(411681);std::vector<std::uint32_t> mods{2,3,4,5,7,8,9,16,17,27,31,32,127,128,256,257,65535,65536,65537,2147483647u,2147483648u,3486784401u,4293001441u,4294967291u,4294967294u,4294967295u};for(unsigned bit=1;bit<=31;++bit){const auto x=std::uint32_t{1}<<bit;mods.push_back(x);if(x>2)mods.push_back(x-1);mods.push_back(x+1);}for(unsigned i=0;i<1000;++i)mods.push_back(static_cast<std::uint32_t>(rng())|2u);
 for(auto m:mods){BinomialMod::PrimePower f(m,m,1);for(U n:{U{0},U{1},U{m-1},U{m},U{m}+1,top,top-1,top-m,top-m+1,(U{4294967295}*4294967294u)/2})REQUIRE(BinomialMod::reduce(n,f)==n%m);for(unsigned i=0;i<1000;++i){const U n=rng()&top;REQUIRE(BinomialMod::reduce(n,f)==n%m);}}
 for(std::uint32_t a:{1u,3u,5u,7u,2147483647u,2147483649u,4294967295u}){const auto actual=BinomialMod::inverse_binary(a);REQUIRE(actual==inverse_bits(a));REQUIRE(static_cast<U>(a)*actual%(U{1}<<32)==1);}
 for(unsigned i=0;i<1000000;++i){const auto a=static_cast<std::uint32_t>(rng())|1u;const auto actual=BinomialMod::inverse_binary(a);REQUIRE(actual==inverse_bits(a));REQUIRE(static_cast<U>(a)*actual%(U{1}<<32)==1);}
 std::cout<<"{\"moduli\":"<<mods.size()<<",\"checks\":"<<checks<<"}\n";}

