#include <algorithm>
#include <array>
#include <bit>
#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <initializer_list>
#include <iostream>
#include <limits>
#include <random>
#include <stdexcept>
#include <vector>
#define private public
#include BINOMIAL_SOURCE
#undef REINSIRK_BINOMIAL_MOD_DEFINED
#define BinomialMod BaselineBinomialMod
#include "reference_e.cpp"
#undef BinomialMod
#undef private
static std::uint64_t checks=0,queries=0,zeros=0,budget_errors=0,table_checks=0;
#define REQUIRE(x)do{++checks;if(!(x)){std::cerr<<"failed "<<__LINE__<<" "<<#x<<'\n';std::abort();}}while(false)
static std::uint32_t tiny_choose(std::uint32_t n,std::uint32_t k,std::uint32_t p){if(k>n)return 0;std::uint64_t r=1;for(std::uint32_t i=1;i<=k;++i)r=r*(n-k+i)/i;return static_cast<std::uint32_t>(r%p);}
static std::uint32_t lucas_reference(std::int64_t n,std::int64_t k,std::uint32_t p){if(n<0||k<0||k>n)return 0;std::uint32_t r=1;while(k){r=r*tiny_choose(n%p,k%p,p)%p;n/=p;k/=p;}return r;}
struct Digit{std::uint32_t n,k;};
template<std::uint32_t P>void direct_table(){for(std::uint32_t n=0;n<P;++n)for(std::uint32_t k=0;k<P;++k){Digit d{n,k};REQUIRE(BinomialMod::lucas_small<P>(&d,1)==tiny_choose(n,k,P));++table_checks;}
 std::mt19937 rng(P+411677);std::array<Digit,63> ds{};for(unsigned count=0;count<=63;++count){std::uint32_t expected=1;for(unsigned i=0;i<count;++i){ds[i]={static_cast<std::uint32_t>(rng()%P),static_cast<std::uint32_t>(rng()%P)};expected=expected*tiny_choose(ds[i].n,ds[i].k,P)%P;}REQUIRE(BinomialMod::lucas_small<P>(ds.data(),count)==expected);++table_checks;}}
int main(){direct_table<19>();direct_table<23>();direct_table<29>();direct_table<31>();
 for(std::uint32_t p:{19u,23u,29u,31u})for(auto limit:{p-2,p-1})for(auto initial:{0u,1u,p-2})for(std::uint64_t budget:{0u,128u}){
  BinomialOptions options;options.table_limit=limit;options.max_multiplicative_steps=budget;BinomialMod b(p,initial,options);BaselineBinomialMod old(p,initial,options);
  auto compare=[&](std::int64_t n,std::int64_t k){const auto want=lucas_reference(n,k,p);const auto before=b.factors_[0].fac.size();std::uint32_t x=0,y=0;bool fail=false,oldfail=false;try{x=b.COM(n,k);}catch(const std::length_error&){fail=true;++budget_errors;}try{y=old.COM(n,k);}catch(const std::length_error&){oldfail=true;}++queries;REQUIRE(fail==oldfail);if(!fail){REQUIRE(x==want);REQUIRE(y==want);}if(want==0){++zeros;REQUIRE(!fail);REQUIRE(b.factors_[0].fac.size()==before);}return fail;};
  const auto size=b.factors_[0].fac.size();compare(static_cast<std::int64_t>(p)*p+2*p-1,2*p+2);REQUIRE(b.factors_[0].fac.size()==size);
  compare(static_cast<std::int64_t>(p)*p+p-1,(p-1)/2);if(limit==p-1)REQUIRE(b.factors_[0].fac.size()==p);else REQUIRE(b.factors_[0].fac.size()<p);
  for(std::int64_t n=0;n<=2*p+2;++n)for(std::int64_t k=-1;k<=n+1;++k)compare(n,k);
  b.prepare(limit);old.prepare(limit);REQUIRE(b.factors_[0].fac.size()==limit+1);REQUIRE((b.factors_[0].fac.size()==p)==(limit==p-1));
  for(std::int64_t n:{static_cast<std::int64_t>(p)*p-1,static_cast<std::int64_t>(p)*p*p+2*p+1,std::numeric_limits<std::int64_t>::max()})for(std::int64_t k:{0,1,2,3,5,10,17,31,63}){const bool failed=compare(n,k);if(limit==p-1)REQUIRE(!failed);}
 }
 REQUIRE(budget_errors>0);std::cout<<"{\"checks\":"<<checks<<",\"queries\":"<<queries<<",\"mathematical_zeros\":"<<zeros<<",\"budget_errors\":"<<budget_errors<<",\"direct_table_checks\":"<<table_checks<<"}\n";}
